// Earnings API Timing'den gelen günlük earnings calendar verisini al.
// Input'u Clear node'undan değil, doğrudan API node'undan okuyoruz.
const data = $('Earnings API Timing').first().json;

const results = [];

// ==========================================
// BMO / PRE-MARKET
// ==========================================
for (const company of data.pre || []) {
  results.push({
    json: {
      symbol: company.symbol,
      companyName: company.name,
      earningsDate: data.date,
      earningsTiming: 'BMO'
    }
  });
}

// ==========================================
// AMC / AFTER-MARKET
// ==========================================
for (const company of data.after || []) {
  results.push({
    json: {
      symbol: company.symbol,
      companyName: company.name,
      earningsDate: data.date,
      earningsTiming: 'AMC'
    }
  });
}

// ==========================================
// TIMING NOT SUPPLIED
// ==========================================
for (const company of data.notSupplied || []) {
  results.push({
    json: {
      symbol: company.symbol,
      companyName: company.name,
      earningsDate: data.date,
      earningsTiming: 'UNKNOWN'
    }
  });
}

return results;

