// ==========================================
// FYNBEAT EARNINGS PREMIUM
// BUILD EARNINGS TWEET
// ==========================================

const {
  symbol,
  epsActual,
  epsEstimated,
  epsSurprise,
  revenueActual,
  revenueEstimated,
  revenueSurprise
} = $json;

// Dört bilanço alanı zorunlu
const values = [
  epsActual,
  epsEstimated,
  revenueActual,
  revenueEstimated
];

if (!values.every(
  value => typeof value === 'number' && Number.isFinite(value)
)) {
  throw new Error('Cannot build tweet: invalid earnings data.');
}

function formatEPS(value) {
  return value < 0
    ? `-$${Math.abs(value).toFixed(2)}`
    : `$${value.toFixed(2)}`;
}

function formatRevenue(value) {
  return `$${(value / 1e9).toFixed(2)}B`;
}

function getResult(actual, estimated, surprise) {
  if (estimated === 0) {
    if (actual > 0) return '📈 Beat (N/A%)';
    if (actual < 0) return '📉 Miss (N/A%)';
    return '➖ In Line (N/A%)';
  }

  const rawSurprise =
    ((actual - estimated) / Math.abs(estimated)) * 100;

  const displayPercent = Math.abs(rawSurprise).toFixed(2);

  if (actual > estimated) {
    return `📈 +${displayPercent}% Beat`;
  }

  if (actual < estimated) {
    return `📉 -${displayPercent}% Miss`;
  }

  return '➖ 0.00% In Line';
}

const lines = [
  `🚨 $${symbol} Earnings`,
  '',
  `EPS: ${formatEPS(epsActual)} vs ${formatEPS(epsEstimated)} est.`,
  getResult(epsActual, epsEstimated, epsSurprise),
  '',
  `Revenue: ${formatRevenue(revenueActual)} vs ${formatRevenue(revenueEstimated)} est.`,
  getResult(revenueActual, revenueEstimated, revenueSurprise)
];

const tweet = lines.join('\n').trim();

return {
  json: {
    ...$json,
    tweet
  }
};

// ==========================================
// FYNBEAT EARNINGS PREMIUM
// VALIDATE TWEET BEFORE X PUBLISH
// FAIL CLOSED
// ==========================================

const items = $input.all();

return items
  .filter(item => {
    const tweet = item.json.tweet;

    // Tweet geçerli bir metin olmalı
    if (typeof tweet !== 'string') {
      return false;
    }

    // Boş veya yalnızca boşluk içeren tweet'i reddet
    if (tweet.trim().length === 0) {
      return false;
    }

    // X için ihtiyatlı karakter sınırı
    if ([...tweet].length > 275) {
      return false;
    }

    return true;
  })
  .map(item => ({
    json: item.json,
    pairedItem: item.pairedItem
  }));

// ==========================================
// FYNBEAT EARNINGS PREMIUM
// CALCULATE EPS & REVENUE SURPRISE
// ==========================================

const epsActual = $json.epsActual;
const epsEstimated = $json.epsEstimated;

const revenueActual = $json.revenueActual;
const revenueEstimated = $json.revenueEstimated;

// Dört alan da geçerli sayı olmalı
const values = [
  epsActual,
  epsEstimated,
  revenueActual,
  revenueEstimated
];

if (!values.every(
  value => typeof value === 'number' && Number.isFinite(value)
)) {
  throw new Error(
    'Invalid earnings data: EPS or Revenue values missing.'
  );
}

// Güvenli sürpriz hesaplaması
function calculateSurprise(actual, estimated) {
  if (estimated === 0) {
    return null;
  }

  const surprise =
    ((actual - estimated) / Math.abs(estimated)) * 100;

  if (!Number.isFinite(surprise)) {
    return null;
  }

  return Number(surprise.toFixed(2));
}

const epsSurprise = calculateSurprise(
  epsActual,
  epsEstimated
);

const revenueSurprise = calculateSurprise(
  revenueActual,
  revenueEstimated
);

return {
  json: {
    ...$json,

    earningsDate: $json.earningsDate ?? $json.date,

    epsSurprise,
    revenueSurprise
  }
};

return {
  json: {
    symbol: $json.symbol,
    companyName: $json.companyName,
    earningsDate: $json.earningsDate,
    earningsTiming: $json.earningsTiming,

    epsActual: $json.epsActual,
    epsEstimated: $json.epsEstimated,
    epsSurprise: $json.epsSurprise,

    revenueActual: $json.revenueActual,
    revenueEstimated: $json.revenueEstimated,
    revenueSurprise: $json.revenueSurprise
  }
};

// ABD piyasa saatini baz al.
// America/New_York timezone DST'yi otomatik yönetir.
const nowNY = $now.setZone('America/New_York');

const hour = nowNY.hour;
const minute = nowNY.minute;
const currentMinutes = hour * 60 + minute;

// BMO polling: 06:00–10:00 New York
const bmoStart = 6 * 60;
const bmoEnd   = 10 * 60;

// AMC polling: 15:00–19:00 New York
const amcStart = 15 * 60;
const amcEnd   = 19 * 60;

let activeWindow = null;

// Earnings tarihi artık New York takvim tarihine göre belirleniyor
const watchlistDate = nowNY.toFormat('yyyy-MM-dd');

// BMO
if (currentMinutes >= bmoStart && currentMinutes < bmoEnd) {
  activeWindow = 'BMO';
}

// AMC
if (currentMinutes >= amcStart && currentMinutes < amcEnd) {
  activeWindow = 'AMC';
}

// Aktif polling penceresinde değilsek workflow burada durur
if (!activeWindow) {
  return [];
}

return [
  {
    json: {
      activeWindow,
      watchlistDate,
      checkedAtNY: nowNY.toISO()
    }
  }
];

// ==========================================
// FYNBEAT EARNINGS PREMIUM
// MATCH FMP EARNINGS WITH DAILY WATCHLIST
// SYMBOL + EARNINGS DATE VALIDATION
// FAIL CLOSED
// ==========================================

// 1. Aktif Premium watchlist şirketlerini al
const watchlist = $input.all().map(item => item.json);

// 2. FMP Earnings Calendar verilerini al
const rawFmp = $('FMP Poll Current Earnings')
  .all()
  .map(item => item.json);

// 3. FMP response formatlarını normalize et
const fmpReports = rawFmp.flatMap(item => {
  if (Array.isArray(item)) {
    return item;
  }

  if (Array.isArray(item.data)) {
    return item.data;
  }

  return [item];
});

// 4. Premium watchlist'i sembol bazında hazırla
const watchlistBySymbol = new Map(
  watchlist
    .filter(company =>
      typeof company.symbol === 'string' &&
      company.symbol.trim() !== '' &&
      typeof company.earningsDate === 'string' &&
      /^\d{4}-\d{2}-\d{2}$/.test(company.earningsDate)
    )
    .map(company => [
      company.symbol.trim().toUpperCase(),
      company
    ])
);

const matched = [];

// 5. FMP raporlarını eşleştir
for (const report of fmpReports) {

  if (!report || typeof report !== 'object') {
    continue;
  }

  const symbol = String(report.symbol ?? '')
    .trim()
    .toUpperCase();

  if (!symbol) {
    continue;
  }

  // Şirket aktif Premium watchlist'te mi?
  const company = watchlistBySymbol.get(symbol);

  if (!company) {
    continue;
  }

  // 6. Bilanço tarihi güvenlik kontrolü
  const reportDate = String(report.date ?? '').trim();
  const watchlistDate = company.earningsDate;

  // Eksik, geçersiz veya farklı tarih reddedilir
  if (
    !/^\d{4}-\d{2}-\d{2}$/.test(reportDate) ||
    reportDate !== watchlistDate
  ) {
    continue;
  }

  // 7. Doğrulanmış bilanço kaydını oluştur
  matched.push({
    json: {
      ...company,
      ...report,

      // Kritik metadata watchlist'ten alınır
      symbol: company.symbol,
      companyName: company.companyName,
      earningsDate: company.earningsDate,
      earningsTiming: company.earningsTiming,
      marketCap: company.marketCap
    }
  });
}

// 8. Eşleşme yoksa boş çıktı
return matched;

// ==========================================
// FYNBEAT EARNINGS PREMIUM
// VALIDATE X PUBLISH SUCCESS
// FAIL CLOSED
// ==========================================

// X Create Tweet node'unun yanıtı
const response = $input.item.json;

// X API başarılı tweet oluşturduğunda
// genellikle data.id döndürür.
const tweetId = response.data?.id ?? response.id;

// Geçerli tweet ID'si zorunlu
if (
  (typeof tweetId !== 'string' &&
   typeof tweetId !== 'number') ||
  !/^\d+$/.test(String(tweetId))
) {
  throw new Error(
    'X publish validation failed: valid tweet ID missing.'
  );
}

// Başarılı yayın doğrulandı.
// Sonraki node Posted Earnings kaydını oluşturabilir.
return {
  json: {
    ...response,
    xPublishValidated: true,
    publishedTweetId: String(tweetId)
  }
};
